            { "id": "submittername", "label": "Submitter", "type": "string", "direction": "input", "binding": "vars.getExpenseDetails1.output.submitterName" },
            { "id": "amount", "label": "Amount", "type": "number", "direction": "input", "binding": "vars.getExpenseDetails1.output.amount" },
            { "id": "category", "label": "Category", "type": "string", "direction": "input", "binding": "vars.getExpenseDetails1.output.category" },
            { "id": "rejectionreason", "label": "Rejection Reason", "type": "string", "direction": "output", "variable": "vars.rejectionReason", "required": false }
          ],
          "outcomes": [
            { "id": "approve", "name": "Approve", "type": "string", "isPrimary": true, "action": "Continue" },
            { "id": "reject", "name": "Reject", "type": "string", "isPrimary": false, "action": "Continue" }
          ]
        }
